#!/usr/bin/env node
/**
 * One-shot Telegram fresh pull for look-tg (temp).
 */
import fs from "node:fs";
import path from "node:path";
import { loadEnv } from "../src/config.mjs";
import { telegramApi } from "../src/telegramApi.mjs";

const env = await loadEnv();
const base = path.resolve(
  "D:\\.1 Work Stations\\RootMC\\Server Handoffs\\Ava Ivy\\data",
);

function lastN(file, n = 40) {
  if (!fs.existsSync(file)) return [];
  const lines = fs
    .readFileSync(file, "utf8")
    .replace(/^\uFEFF/, "")
    .trim()
    .split(/\n+/)
    .filter(Boolean);
  return lines.slice(-n).map((l) => {
    try {
      return JSON.parse(l);
    } catch {
      return { raw: l };
    }
  });
}

let updates = [];
try {
  updates = await telegramApi(
    "getUpdates",
    {
      offset: -80,
      limit: 80,
      timeout: 0,
      allowed_updates: ["message", "edited_message", "my_chat_member"],
    },
    env,
  );
  console.log("=== getUpdates count", updates.length);
} catch (e) {
  console.log("=== getUpdates ERR", e.message);
}

for (const u of updates) {
  const msg = u.message || u.edited_message;
  if (!msg) {
    console.log("upd", u.update_id, Object.keys(u));
    continue;
  }
  console.log(
    "UPD",
    JSON.stringify({
      uid: u.update_id,
      chat: msg.chat?.id,
      title: msg.chat?.title || msg.chat?.username || msg.chat?.first_name,
      mid: msg.message_id,
      from: msg.from?.id,
      uname: msg.from?.username,
      text: String(msg.text || msg.caption || "").slice(0, 400),
      reply_to: msg.reply_to_message?.message_id,
    }),
  );
}

const ffInbound = lastN(
  path.join(base, "telegram/groups/-1003868178598/inbound.jsonl"),
  60,
);
console.log("\n=== FERN FOREST inbound last", ffInbound.length);
for (const m of ffInbound) {
  const t = m.text || m.content || m.body || "";
  console.log(
    JSON.stringify({
      id: m.messageId || m.id,
      from: m.authorId || m.fromId,
      at: m.at,
      text: String(t).slice(0, 280),
      mentioned: m.mentioned ?? m.botMentioned ?? null,
    }),
  );
}

const globInbound = lastN(path.join(base, "logs/inbound.jsonl"), 120);
const tgIn = globInbound.filter(
  (m) =>
    String(m.channelId || m.channel || "").includes("tg:") ||
    m.surface === "telegram",
);
console.log("\n=== global inbound tg", tgIn.length);
for (const m of tgIn.slice(-50)) {
  console.log(
    JSON.stringify({
      id: m.messageId || m.id,
      ch: m.channelId || m.channel,
      from: m.authorId || m.userId,
      at: m.at,
      text: String(m.text || m.content || "").slice(0, 280),
    }),
  );
}

const utt = lastN(path.join(base, "training/utterances.jsonl"), 80);
const tgUtt = utt.filter(
  (m) =>
    String(m.channelId || "").includes("tg:") || m.surface === "telegram",
);
console.log("\n=== utterances tg", tgUtt.length);
for (const m of tgUtt.slice(-30)) {
  console.log(
    JSON.stringify({
      id: m.messageId || m.id,
      ch: m.channelId,
      kind: m.kind,
      at: m.at,
      text: String(m.content || m.text || "").slice(0, 220),
    }),
  );
}

const out = lastN(path.join(base, "logs/outbound.jsonl"), 100);
const tgOut = out.filter(
  (m) =>
    String(m.channelId || "").includes("tg:") || m.surface === "telegram",
);
console.log("\n=== outbound tg", tgOut.length);
for (const m of tgOut.slice(-30)) {
  console.log(
    JSON.stringify({
      id: m.messageId || m.id,
      ch: m.channelId,
      kind: m.kind,
      at: m.at,
      chars: m.chars,
      text: String(m.content || m.text || "").slice(0, 220),
    }),
  );
}

// list telegram dir
function walk(dir, acc = []) {
  if (!fs.existsSync(dir)) return acc;
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(p, acc);
    else acc.push(p);
  }
  return acc;
}
const tgFiles = walk(path.join(base, "telegram"))
  .map((p) => ({
    p,
    mtime: fs.statSync(p).mtimeMs,
    size: fs.statSync(p).size,
  }))
  .sort((a, b) => b.mtime - a.mtime)
  .slice(0, 30);
console.log("\n=== telegram files recent");
for (const f of tgFiles) {
  console.log(new Date(f.mtime).toISOString(), f.size, f.p);
}

